['// 구글 번역 초기화 (API 로드 후 자동 호출)
    function googleTranslateElementInit() {
        new google.translate.TranslateElement({
            pageLanguage: 'ko',
            includedLanguages: 'en,ko',
            autoDisplay: false,
            multilanguagePage: true
        }, 'google_translate_element');
    }

    // 현재 언어 쿠키에서 가져오기
    function getCurrentLang() {
        const match = document.cookie.match(/googtrans=\/(auto|ko)\/(\w+)/);
        return match ? match[2] : 'ko';
    }

    $(function() {
        // 구글 번역 select가 생성될 때까지 반복 체크
        function waitGTCombo(callback) {
            const gtcombo = document.querySelector('.goog-te-combo');
            if (gtcombo) {
                callback(gtcombo);
            } else {
                setTimeout(() => waitGTCombo(callback), 200);
            }
        }

        // 언어 변경 이벤트
        function changeLanguage(event) {
            const target = event.target.closest('a[data-lang]');
            if (!target) return;
            event.preventDefault();

            const lang = target.dataset.lang;
            waitGTCombo(gtcombo => {
                gtcombo.value = lang;
                gtcombo.dispatchEvent(new Event('change'));
            });

            // 버튼 텍스트 변경
            const btn = target.closest('.lang').querySelector('button');
            if (btn) btn.textContent = lang.toUpperCase();
        }

        // PC, 모바일 언어 버튼 이벤트 연결
        document.querySelectorAll('.lang').forEach(langDiv => {
            langDiv.addEventListener('click', changeLanguage);
        });

        // 초기 버튼 언어 세팅
        const currentLang = getCurrentLang();
        document.querySelectorAll('.lang button').forEach(btn => {
            btn.textContent = currentLang.toUpperCase();
        });

        // 뒤로가기 시 새로고침은 선택적
        $(window).on("pageshow", function(event) {
            if (event.originalEvent.persisted) {
                location.reload();
            }
        });
    });', '// 쿠키 함수
    function setCookie(name, value, days) { 
        const date = new Date();
        date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
        document.cookie = name + "=" + encodeURIComponent(value) + "; path=/; expires=" + date.toUTCString();
    }

    function getCookie(name) {
        const cookies = document.cookie.split('; ');
        for (let i = 0; i < cookies.length; i++) {
            const [key, val] = cookies[i].split('=');
            if (key === name) return decodeURIComponent(val);
        }
        return null;
    }

    $(document).ready(function() {
        $('#main_pop .pop_up').each(function(index) {
            const popupId = $(this).attr('id');

            // 해당 팝업 쿠키 체크
            if (getCookie('popupClosed_' + popupId) === 'Y') {
                $(this).hide();
            } else {
                $(this).show();
            }
        });

        // 닫기 / 오늘하루닫기 이벤트
        $('.close_pop').click(function(e) {
            e.preventDefault();
            const parentPop = $(this).closest('.pop_up');
            const popupId = parentPop.attr('id');

            if ($(this).text().includes('오늘하루닫기')) {
                setCookie('popupClosed_' + popupId, 'Y', 1); // 1일간 쿠키 저장
            }

            parentPop.hide();
        });
    });', '평창송어축제, 20주년 맞아 다채로운 프로그램으로 돌아온다', '미취학아동(2026년 초등학교 입학예정)은 보호자 동반하에 무료입장입니다.초등학생, 성인은 각 항목별 매표소 요금표를 참고하시기 바랍니다.']

