['행사 · 축제 : 영암문화관광재단', '공식행사/대표프로그램/체험 및 전시/기타 연계행사 등', '$(".title").remove();

// 모달 요소를 가져옵니다.
var modal = document.getElementById("applicationModal");

// '신청' 버튼 요소를 가져옵니다.
var btn = document.getElementById("application_button");

// '닫기' 버튼 요소를 가져옵니다.
var span = document.getElementsByClassName("close")[0];

// '신청' 버튼 클릭 이벤트 리스너
btn.onclick = function () {
    //console.log("open");
    modal.style.display = "block";
};

// '닫기' 버튼 클릭 이벤트 리스너
span.onclick = function () {
    modal.style.display = "none";
};

// 모달 외부 클릭 시 모달 닫기
window.onclick = function (event) {
    if (event.target == modal) {
        modal.style.display = "none";
    }
};

function checkItems() {
	  var s='';
		var name  = $('input[id="name"]').val();
		var hp    = $('input[id="hp"]').val();
		var age   = $('input[id="age"]').val();
		var num   = $('input[id="num"]').val();

		if (!name) {
			s=s+'성명\n';
		}
		if (!hp) {
			s=s+'연락처\n';
		}
		if (!age) {
			s=s+'나이\n';
		}
		if (!num) {
			s=s+'참석자수\n';
		}

		return s;
};


document.addEventListener("DOMContentLoaded", function () {

	document.getElementById("submitApplication").addEventListener("click", function () {

	var s=checkItems();
	if (s) {
			alert(s+'확인하십시오.');			
			return false;			
	};


	if (!confirm("제출할까요?")) 
	{
		return false;
	}

	var formData = new FormData();
	formData.append("ntId",   159);
	formData.append("ntTitle","2025 마한역사문화제 ");	
	formData.append("nrName", document.getElementById("name").value);
	formData.append("nrHp",   document.getElementById("hp").value);
	formData.append("nrAge",  document.getElementById("age").value);
	formData.append("nrNum",  document.getElementById("num").value);

		$.ajax({
	    url: "?act=saveRequest",
	    type: 'POST',
			processData: false, // 필수 
			contentType: false, // 필수 
			data: formData,
			success: function(data) {
				alert("신청이 완료되었습니다.");
				modal.style.display = "none";
			}
		});


  });
});', '✕영암문화관광재단 개인정보 처리방침영암문화관광재단은 정보주체의 자유와 권리 보호를 위해 「개인정보 보호법」 및
                  관계 법령이 정한 바를 준수하여, 적법하게 개인정보를 처리하고 안전하게
                  관리하고 있습니다. 이에 「개인정보 보호법」 제30조에 따라 정보주체에게
                  개인정보 처리에 관한 절차 및 기준을 안내하고, 이와 관련한 고충을 신속하고
                  원활하게 처리할 수 있도록 하기 위하여 다음과 같이 개인정보 처리방침을
                  수립·공개합니다.제1조(개인정보의 처리 목적)① 영암문화관광재단은 다음의 목적을 위하여 개인정보를 처리합니다. 처리하고
                  있는 개인정보는 다음의 목적 이외의 용도로는 이용되지 않으며, 이용 목적이
                  변경되는 경우에는 「개인정보 보호법」 제18조에 따라 별도의 동의를 받는 등
                  필요한 조치를 이행할 예정입니다.1. 홈페이지 회원 가입 및 관리- 회원가입 의사 확인, 회원제 서비스 제공에 따른 본인 식별·인증, 회원자격
                  유지·관리, 서비스 부정이용 방지, 만14세 미만 아동의 개인정보 처리 시
                  법정대리인의 동의여부 확인, 각종 고지·통지, 고충처리 등 목적으로 개인정보를
                  처리합니다.2. 민원사무 처리- 민원인의 신원 확인, 민원사항 확인, 사실조사를 위한 연락·통지, 처리결과
                  통보 등의 목적으로 개인정보를 처리합니다.3. 재화 또는 서비스 제공- 경연, 행사, 공연, 교육 등의 문화·관광 프로그램 참여자 등록, 물품 배송,
                  서비스 제공, 계약서·청구서 발송, 콘텐츠 제공, 맞춤서비스 제공, 본인인증,
                  요금결제·정산, 채권추심 등을 목적으로 개인정보를 처리합니다.4. 마케팅 및 광고에의 활용- 신규 서비스(제품) 개발 및 맞춤 서비스 제공, 이벤트 및 광고성 정보 제공 및
                  참여기회 제공, 인구통계학적 특성에 따른 서비스 제공 및 광고 게재, 서비스의
