}', 'function getDaysLeft(dateStr){
    const [y, m, d] = dateStr.split('-').map(Number);
    const today = new Date();
    const event = new Date(y, m - 1, d);
    today.setHours(0, 0, 0, 0);
    event.setHours(0, 0, 0, 0);
    return Math.max(0, Math.ceil((event - today) / 86400000));
  }

  function syncDdayBox(){
    const badge = document.querySelector('.time-badge');   // <img>
    const box   = document.querySelector('.d-day-text');   // 오버레이
    const inner = document.querySelector('.bannerInner');  // 기준 컨테이너
    if (!badge || !box || !inner) return;

    const b = badge.getBoundingClientRect();
    const i = inner.getBoundingClientRect();

    box.style.top    = (b.top - i.top) + 'px';
    box.style.left   = (b.left - i.left) + 'px';
    box.style.width  = b.width + 'px';
    box.style.height = b.height + 'px';
  }

  // ✅ DOM 준비 완료 시점
  document.addEventListener('DOMContentLoaded', () => {
    const box = document.querySelector('.d-day-text');
    if (!box) return;

    // D-Day 숫자 그리드 채우기
    box.innerHTML = `
      <div class="grid">
        <span class="digit"></span>
        <span class="digit"></span>
        <span class="digit"></span>
        <span class="digit"></span>
      </div>
    `;

    const target = '2025-10-17';              // ★ 행사일
    const days = getDaysLeft(target);
    const padded = String(days).padStart(2, '0'); // 예: 45 → "045"

    const cells = box.querySelectorAll('.digit');
    cells.forEach(c => c.textContent = '');
    for (let i = 0; i < padded.length && i < cells.length; i++) {
      cells[cells.length - 1 - i].textContent = padded[padded.length - 1 - i];
    }

    // ✅ 이미지 로딩 후 위치 동기화
    const badge = document.querySelector('.time-badge');
    if (badge) {
      if (badge.complete) {
        syncDdayBox();
      } else {
        badge.onload = syncDdayBox;
      }
    }

    // ✅ 화면 리사이즈 시 재계산
    window.addEventListener('resize', syncDdayBox);
  });

  // ✅ 전체 리소스 로드 이후에도 다시 위치 보정
  window.addEventListener('load', syncDdayBox);', '장소 : 청도야외공연장 일원']

