['/* ====== 팝업 공통 설정 ====== */
const HIDE_HOURS = 24; // 24시간 숨김
const STORAGE_KEYS = { popup1: 'popup1ClosedAt', popup2: 'popup2ClosedAt' };

/* 요소 참조 (없어도 안전하게 처리) */
const overlay = document.getElementById('overlay'); // 없으면 null
const popup1 = document.getElementById('popup1');
const popup2 = document.getElementById('popup2');
const popups = [popup1, popup2].filter(Boolean); // 존재하는 것만 사용

/* 유틸 */
const nowMs = () => Date.now();
const ms24h = HIDE_HOURS * 60 * 60 * 1000;
function shouldShow(key){
  const ts = localStorage.getItem(key);
  if(!ts) return true;
  return (nowMs() - Number(ts)) > ms24h;
}

/* 오버레이 표시/숨김 (overlay가 없으면 조용히 패스) */
function anyPopupVisible(){
  return popups.some(p => p.style.display !== 'none' && getComputedStyle(p).display !== 'none');
}
function updateOverlay(){
  if(!overlay) return; // overlay 없는 레이아웃 대응
  if(anyPopupVisible()){
    overlay.classList.add('is-visible');
    overlay.setAttribute('aria-hidden', 'false');
  }else{
    overlay.classList.remove('is-visible');
    overlay.setAttribute('aria-hidden', 'true');
  }
}

/* 팝업 열고/닫기 */
function openPopup(el){
  if(!el) return;
  el.style.display = 'block';
  updateOverlay();
}
function closePopup(el){
  if(!el) return;
  el.style.display = 'none';
  updateOverlay();
}
function closeForDay(key, el){
  localStorage.setItem(key, String(nowMs()));
  closePopup(el);
}

/* 초기 실행: 표시 조건 확인 후 열기 */
window.addEventListener('DOMContentLoaded', () => {
  if(popup1 && shouldShow(STORAGE_KEYS.popup1)) openPopup(popup1);
  if(popup2 && shouldShow(STORAGE_KEYS.popup2)) openPopup(popup2);
});

/* 클릭 이벤트 위임: 닫기 버튼들 처리 & 오버레이 클릭 닫기 */
document.addEventListener('click', (e) => {
  // data-close="popup1|popup2"  (X 버튼 등)
  const x = e.target.closest('[data-close]');
  if(x){
    const id = x.getAttribute('data-close');
    closePopup(document.getElementById(id));
    return;
  }

  // data-close-now="popup1|popup2"
  const nowBtn = e.target.closest('[data-close-now]');
  if(nowBtn){
    const id = nowBtn.getAttribute('data-close-now');
    closePopup(document.getElementById(id));
    return;
  }

  // data-close-day="popup1|popup2"
  const dayBtn = e.target.closest('[data-close-day]');
  if(dayBtn){
    const id = dayBtn.getAttribute('data-close-day');
    const key = STORAGE_KEYS[id];
    closeForDay(key, document.getElementById(id));
    return;
  }

  // 오버레이 클릭 시 모두 닫기 (overlay 있을 때만)
  if(overlay && e.target === overlay){
    popups.forEach(p => closePopup(p));
  }
});

/* ESC로 닫기 */
document.addEventListener('keydown', (e) => {
  if(e.key === 'Escape'){
    popups.forEach(p => closePopup(p));
  }
});']

