['/* =============== 종이 꽃가루(사각) 모양 오버라이드 =============== */
/* 애니메이션, 위치, transform 등은 전혀 바꾸지 않음 (모양만 변경) */

:root {
  /* 필요 시 색상만 바꿔 쓰세요 */
  --paper-1: #ffd86b;  /* honey */
  --paper-2: #ffe08a;  /* light yellow */
  --paper-3: #fff0c2;  /* cream */
  --paper-4: #ffdba6;  /* pastel peach */

  --popup-width: min(360px, 92vw);
--popup-radius: 14px;
--shadow: 0 12px 30px rgba(0,0,0,.18);
--border: 1px solid rgba(0,0,0,.1);
}

.sakura {
  /* 모양: 꽃잎 → 네모 종이 */
  background: var(--paper-1) !important;
  background-image: none !important;       /* 기존 배경 제거 */
  color: transparent !important;            /* 이모지/문자 렌더 차단 */
  border-radius: 1px !important;            /* 거의 직각 */

  /* 살짝 종이결 느낌 – 테두리만 약하게 */
  box-shadow: inset 0 0 0 .5px rgba(0,0,0,.15),
              0 .4px .8px rgba(0,0,0,.08) !important;

  /* 혹시 라이브러리가 마스크/필터로 꽃잎 모양을 만들면 강제 해제 */
  -webkit-mask-image: none !important;
  mask-image: none !important;
  filter: none !important;

  /* 크기는 라이브러리 값 그대로 사용(덮어쓰지 않음) */
  /* width/height, transform, animation: 건드리지 않음 */
}

/* 라이브러리가 pseudo 요소로 꽃잎을 올릴 경우 대비 */
.sakura::before,
.sakura::after {
  content: none !important;
  background: none !important;
  -webkit-mask-image: none !important;
  mask-image: none !important;
}

/* 약간 ‘찢어진 종이’ 느낌을 주고 싶은 경우: clip-path만(애니메이션 영향 없음) */
.sakura:nth-child(3n)  { clip-path: polygon(6% 10%, 94% 7%, 92% 90%, 8% 93%); }
.sakura:nth-child(5n)  { clip-path: polygon(10% 6%, 90% 12%, 94% 88%, 7% 92%); }
.sakura:nth-child(7n)  { clip-path: polygon(8% 14%, 92% 9%, 88% 92%, 10% 88%); }

/* 색상만 랜덤 변주(크기/속도/회전 그대로 유지) */
.sakura:nth-child(2n)  { background: var(--paper-2) !important; }
.sakura:nth-child(4n)  { background: var(--paper-3) !important; }
.sakura:nth-child(6n)  { background: var(--paper-4) !important; }


