		html+= '		<span>전화번호 : <a href="tel:'+data.telNo+'">'+data.telNo+'</a></span>';
	}
	html+= '		</div>';
	html+= '		<ul class="desc_btn">';
	html+= '			<li class="info"><a href="javascript:viewTourInfo(\'/tour\',\''+data.gubun+'\',\''+data.category+'\',\''+data.infoId+'\');"><span>상세정보</span></a></li>';
	html+= '			<li class="close"><a href="javascript:closeMapInfoWindow();"><span>닫기</span></a></li>';
	html+= '		</ul>';
	html+= '		<a href="javascript:closeMapInfoWindow();" class="map_marker_close"><img src="/modules/tour/img/map_marker_close.png" alt="닫기" /></a>';
	html+= '	</div>';

	return html;
}

function MapInfoWindow(marker, data)
{
	var infowindow = new daum.maps.CustomOverlay({
		map: map,
	    position: new daum.maps.LatLng(data.locLat, data.locLng),
	    content: MapInfoWindowContent(data),
	    yAnchor: 1
	});
	infowindow.setMap(null);
	infoArray.push(infowindow);

	daum.maps.event.addListener(marker, 'click', function()
	{
		closeMapInfoWindow();
		infowindow.setMap(map);
	});
}

function closeMapInfoWindow()
{
	if (infoArray)
	{
		for (i in infoArray)
		{
			infoArray[i].setMap(null);
		}
	}
}
