['단체 참가신청바로가기', '참가신청 확인/수정바로가기', '// jQuery가 로드되었는지 확인 후 실행
if (typeof $ !== 'undefined') {
	// DOM이 완전히 로드된 후 실행되도록 보장
	$(document).ready(function() {
		// 기존 이벤트 핸들러 모두 제거 (다른 파일에서 바인딩된 것들 포함)
		$(".snb2dDown").off("click");

		/* 모바일용 메뉴바 - 1레벨 메뉴 hide/show 토글 */
		var articleMgnb = $("#snb li.snb"); 
		articleMgnb.addClass("hide"); 
		// active 클래스가 있으면 초기에 show 상태로 설정 (없어도 토글은 작동)
		$("#snb li.active, #snb li.on1.active").each(function(){
			$(this).removeClass("hide").addClass("show"); 
			$(this).find(".snb2dul").show(); 
		});

		/* 모바일용 메뉴바 - 2레벨 메뉴 hide/show 토글 (1레벨과 동일한 방식) */
		// 2레벨 메뉴 초기화 함수
		function initLevel2Menu() {
			// show 클래스가 없는 2레벨 메뉴에만 hide 추가
			$("#snb li.snb ul.snb2dul > li.snb2d, #snb li.snb.show ul.snb2dul > li.snb2d").each(function(){
				if(!$(this).hasClass("show")) {
					$(this).addClass("hide"); 
				}
			});
			// active 클래스가 있으면 초기에 show 상태로 설정 (없어도 토글은 작동)
			$("#snb li.snb ul.snb2dul > li.snb2d.active, #snb li.snb ul.snb2dul > li.snb2d.on2.active").each(function(){
				$(this).removeClass("hide").addClass("show"); 
				$(this).find(".snb3dul").show(); 
			});
		}
		// 초기화 실행
		initLevel2Menu();

		// 1레벨 메뉴 클릭 이벤트 (기존 이벤트 제거 후 새로 바인딩)
		$(document).off("click", ".snb2dDown").on("click", ".snb2dDown", function(e){ 
			e.preventDefault();
			e.stopPropagation();
			var myArticle = $(this).parents("#snb li.snb"); 
			// hide 클래스가 있거나 show 클래스가 없으면 hide 상태로 간주
			if(myArticle.hasClass("hide") || !myArticle.hasClass("show")){ 
				articleMgnb.addClass("hide").removeClass("show"); 
				articleMgnb.find(".snb2dul").slideUp("fast"); 
				myArticle.removeClass("hide").addClass("show"); 
				myArticle.find(".snb2dul").slideDown("fast", function(){
					// 1레벨 메뉴가 펼쳐진 후 2레벨 메뉴 초기화
					initLevel2Menu();
				}); 
			} else { 
				myArticle.removeClass("show").addClass("hide");
				myArticle.find(".snb2dul").slideUp("fast"); 
			} 
			return false;
		});

		$(document).on("click", ".snb3dDown", function(e){ 
			e.preventDefault();
			e.stopPropagation();
			var myArticle2 = $(this).closest("li.snb2d"); 
			// hide 클래스가 없으면 초기화되지 않은 것이므로 hide 추가
			if(!myArticle2.hasClass("hide") && !myArticle2.hasClass("show")) {
				myArticle2.addClass("hide");
			}
			var parentUl = myArticle2.closest("ul.snb2dul");
			var sameLevelArticles = parentUl.find("li.snb2d"); // 같은 레벨의 모든 2레벨 메뉴들
			// hide 클래스가 있거나 show 클래스가 없으면 hide 상태로 간주
			if(myArticle2.hasClass("hide") || !myArticle2.hasClass("show")){ 
				// hide 상태면 같은 레벨의 모든 메뉴를 hide로 만들고 클릭한 것만 show
				sameLevelArticles.addClass("hide").removeClass("show"); 
				sameLevelArticles.find(".snb3dul").slideUp("fast"); 
				myArticle2.removeClass("hide").addClass("show"); 
				myArticle2.find(".snb3dul").slideDown("fast"); 
			} else { 
				// show 상태면 클릭한 것을 hide로 변경
				myArticle2.removeClass("show").addClass("hide");
				myArticle2.find(".snb3dul").slideUp("fast"); 
			} 
			return false;
		});
	});
} else {
	console.log('jQuery가 로드되지 않았습니다.');
}']

['document.addEventListener('DOMContentLoaded', function () {
        const flexWrap = document.querySelector('.flex-wrap');
        let activeIndex = null;

        function bindEvents() {
            const contWraps = document.querySelectorAll('.cont-wrap');
            const isMobile = window.matchMedia('(max-width: 1023px)').matches;
            const duration = isMobile ? 0.3 : 1.2;

            // 기존 이벤트 제거
            contWraps.forEach(el => {
                const newEl = el.cloneNode(true);
                el.replaceWith(newEl);
            });

            const updatedWraps = document.querySelectorAll('.cont-wrap');

            updatedWraps.forEach((el, index) => {
                const link = el.querySelector('.link');

                if (isMobile) {
                    link.addEventListener('click', function (e) {
                        if (activeIndex !== index) {
                            e.preventDefault();
                            activeIndex = index;

                            updatedWraps.forEach(item => item.classList.remove('active'));
                            el.classList.add('active');

                            gsap.to(updatedWraps, {
                                flexGrow: (i) => (i === index ? 1.8 : 1),
                                duration: 0.3,
                                ease: "power1.out"
                            });

                            updatedWraps.forEach((wrap, i) => {
                                const mini = wrap.querySelector('.mini');
                                const activeLogo = wrap.querySelector('.active-logo');

                                activeLogo.classList.remove('show', 'hide');

                                if (i === index) {
                                    mini.style.opacity = '0';
                                    activeLogo.classList.add('show');
                                } else {
                                    mini.style.opacity = '1';
                                    activeLogo.classList.add('hide');
                                }
                            });
                        } else {
                            activeIndex = null;
                        }
                    });
                } else {
                    el.addEventListener('mouseenter', () => {
                        if (activeIndex === index) return;
                        activeIndex = index;

                        updatedWraps.forEach(item => item.classList.remove('active'));
                        el.classList.add('active');

                        gsap.to(updatedWraps, {
                            flexGrow: (i) => (i === index ? 1.8 : 1),
                            duration: 1.2,
                            ease: "power2.inOut"
                        });

                        updatedWraps.forEach((wrap, i) => {
                            const mini = wrap.querySelector('.mini');
                            const activeLogo = wrap.querySelector('.active-logo');

                            activeLogo.classList.remove('show', 'hide');

                            if (i === index) {
                                mini.style.opacity = '0';
                                activeLogo.classList.add('show');
                            } else {
                                mini.style.opacity = '1';
                                activeLogo.classList.add('hide');
                            }
                        });
                    });
                }
            });

            // 마우스 나갔을 때 초기화 (PC 전용)
            if (!isMobile) {
                flexWrap.addEventListener('mouseleave', () => {
                    activeIndex = null;
                    updatedWraps.forEach(item => item.classList.remove('active'));

                    gsap.to(updatedWraps, {
                        flexGrow: 1,
                        duration: 1.2,
                        ease: "power2.inOut"
                    });

                    updatedWraps.forEach((wrap) => {
                        const mini = wrap.querySelector('.mini');
                        const activeLogo = wrap.querySelector('.active-logo');

                        activeLogo.classList.remove('show', 'hide');
                        mini.style.opacity = '1';
                    });
                });
            }
        }

        // 최초 실행
        bindEvents();

        // 리사이즈 시 이벤트 다시 바인딩
        let prevMode = window.innerWidth <= 1023 ? 'mobile' : 'desktop';
        window.addEventListener('resize', () => {
            const currentMode = window.innerWidth <= 1023 ? 'mobile' : 'desktop';
            if (prevMode !== currentMode) {
                prevMode = currentMode;
                bindEvents();
            }
