['공연 전시 행사캘린더', '// 메인 동영상
			$(document).ready(function(){
				$(".mc05_btn").click(function(e){
					e.preventDefault(); // 기본 이벤트 중단 (페이지 이동 방지)

					// 팝업 컨텐츠 생성 및 표시
					var tableHtml = '<iframe id="popupVideo" src="https://www.youtube.com/embed/HEgAsNmE-Fg?si=94zFY5YvRlJpwd3N" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>';
					var popupContent = '<div class="popup_bg"></div>' +
									'<div class="popup_container video_popup">' +
									'<span class="popup_title">평택시문화재단 TV</span>' +
									tableHtml +
									'<span class="close_popup">×</span>' +
									'</div>';

					$("body").append(popupContent);

					// 비디오 자동 재생 및 팝업 닫기 이벤트
					var video = document.getElementById("popupVideo");
					//video.play(); 
					video.onended = function() {
						$(".popup_bg, .popup_container").remove(); // 비디오 재생 종료 후 팝업 닫기
					};

					// 팝업 닫기 버튼 이벤트
					$(".close_popup").click(function(){
						$(".popup_bg, .popup_container").remove();
					});
				});
			});', '// 바텀버튼
   function quickMenu() {
        const quickMenuItems = document.querySelectorAll('.quick_menu  ul > a > li > p');
        quickMenuItems.forEach(item => {
            item.style.maxWidth = "100%";
            item.style.padding = "0 10px";
        });
        setTimeout(() => {
            quickMenuItems.forEach(item => {
                item.removeAttribute('style')
            });
        }, 5000);
    };


      // 퀵메뉴 온 오프

       document.addEventListener('DOMContentLoaded', () => {
        const quickBut = document.querySelector('.quick_but');
        const quickMenuTab = document.querySelector('.quick_menu_Tab');

        // 클릭 이벤트 리스너 추가
        quickBut.addEventListener('click', () => {
            // quick_menu_Tab의 현재 상태를 확인하고 토글
            if (quickMenuTab.classList.contains('collapsed')) {
                quickMenuTab.classList.remove('collapsed'); // 보이기
                quickBut.textContent = '퀵메뉴 닫기'; // 텍스트 변경
            } else {
                quickMenuTab.classList.add('collapsed'); // 숨기기
                quickBut.textContent = '퀵메뉴 열기'; // 텍스트 변경
            }
        });
    });', '안정리예술인광장 문화예술프로그램']

