							setViewTime =function(){
									dat_today.setSeconds(dat_today.getSeconds() + 1);
									var diff1 = dat_start - dat_today;
									var diff2 = dat_end - dat_today;									

									var currSec = (1000); 
									var currMin = (60 * 1000); 
									var currHour = (60 * 60 * 1000); 
									var currDay = (24 * 60 * 60 * 1000); 

									//$('.test').html(diff1);
									/* waite */
									if( diff1 > 0 ){ 
										var day = parseInt(diff1/currDay); 
										var hour = parseInt(diff1/currHour); 
										var min = parseInt(diff1/currMin); 
										var sec = parseInt(diff1/currSec); 
										var viewHour = (hour-(day*24));
										var viewMin = (min-(hour*60));
										var viewSec = (sec-(min*60));											

										$('.first_txt').html('축제까지는');
