										$('.remain_hour').html(leadingZeros(viewHour, 2));
										$('.remain_min').html(leadingZeros(viewMin, 2));
										$('.remain_second').html(leadingZeros(viewSec, 2));	


									}else{
										if( diff2 > 0 ){
											var day = parseInt(diff2/currDay); 
											var hour = parseInt(diff2/currHour); 
											var min = parseInt(diff2/currMin); 
											var sec = parseInt(diff2/currSec); 
											var viewHour = (hour-(day*24));
											var viewMin = (min-(hour*60));
											var viewSec = (sec-(min*60));											

											$('.first_txt').html('축제종료까지는');											
											$('.remain_day').html(day);
											$('.remain_hour').html(leadingZeros(viewHour, 2));
											$('.remain_min').html(leadingZeros(viewMin, 2));
											$('.remain_second').html(leadingZeros(viewSec, 2));													
										}else{
											$('.time, .remain_day, .remain_hour, .remain_min, .remain_second, .last_txt, .first_txt').remove();
											$('.festival_end').show();	
										}

									}



							};
							setInterval('setViewTime()',1000)
						});

						/* 일정 자리수 미만이면 앞에 0을 붙이는 함수*/
						function leadingZeros(n, digits) {var zero = '';n = n.toString();if (n.length < digits) {
							for (var i = 0; i < digits - n.length; i++)zero += '0';}return zero + n;
						}"]

