	function initMap(mapItem, coord) {

		var contentString;
		var icon;

		gmarkers = [];

		markers = new Array();
		for(var iter=0 ; iter < coord.length ; iter++) {

			if(coord.length > 1) icon = "/images/google_map/guide_mark_"+(iter+1)+".png";
			else {
				if(coord[iter][6] == 'FOOD') icon = "/images/google_map/marker_food.png";
				else if(coord[iter][6] == 'LODG') icon = "/images/google_map/marker_stay.png";
				else if(coord[iter][6] == 'TOUR') icon = "/images/google_map/marker_mountain.png";	
				else if(coord[iter][6] == 'SHOP') icon = "/images/google_map/marker_shop.png";
				else if(coord[iter][6] == 'TRAFFIC') icon = "/images/google_map/marker_car.png";
				else if(coord[iter][6] == 'MAPCENTER') icon = "/images/google_map/around_point.png";
				else icon = "/images/google_map/marker_mountain.png";
			}

			// 마커 이미지의 이미지 크기 입니다
			imageSize = new kakao.maps.Size(32, 40); 

			// 마커 이미지를 생성합니다
			markerImage = new kakao.maps.MarkerImage(icon, imageSize);

			// 마커 표시할 위치.
			latlng = new kakao.maps.LatLng(coord[iter][2], coord[iter][1]);

			markers[iter] = new kakao.maps.Marker({
				map: map, // 마커를 표시할 지도
				position: latlng, // 마커를 표시할 위치
				title : coord[iter][0], // 마커의 타이틀, 마커에 마우스를 올리면 타이틀이 표시됩니다
				image : markerImage // 마커 이미지 
			});

			// 마커가 지도 위에 표시되도록 설정합니다
			markers[iter].setMap(map);	

			contentString = make_infowindow(coord[iter][3]);
			iter == 0 ? show_infowindow(markers[iter], contentString) : '';
			bind_infowindow(markers[iter], contentString);
			gmarkers.push(markers[iter]);
		}
		map.setCenter(new kakao.maps.LatLng(coord[0][2]+0.004, coord[0][1]));
	}

