	function make_infowindow(item) {
		return "<span class=\"intro_infowindow\">"+item+"</span>";
	}


	function bind_infowindow(marker, contents) {
		kakao.maps.event.addListener(marker, "click", function() {
			show_infowindow(marker, contents);
		});
	}

	function show_infowindow(marker, contents) {
		// 마커를 클릭했을 때 마커 위에 표시할 인포윈도우를 생성합니다
		var iwContent = contents, // 인포윈도우에 표출될 내용으로 HTML 문자열이나 document element가 가능합니다
			iwRemoveable = true; // removeable 속성을 ture 로 설정하면 인포윈도우를 닫을 수 있는 x버튼이 표시됩니다

		if(infowindow != null) infowindow.close();		
		// 인포윈도우를 생성합니다
		infowindow = new kakao.maps.InfoWindow({
			content : iwContent,
			removable : iwRemoveable
		});	

		infowindow.setContent(contents);		
		infowindow.open(map, marker);

		//말풍선 제어
		var map_cont = $(".map_contents");		
		map_cont.unwrap().siblings().remove();
		map_cont.parent().addClass("mapinfo_wrap").css({
			"height":"auto",
			"border":"0",
			"background":"none",
			"z-index": "1"
		});
	}

	// 커스텀 오버레이를 닫기 위해 호출되는 함수입니다 
	function closeOverlay() {
		infowindow.close();		
	}

	function make_infowindow_near(item) {
		var contents_near;
		var title;

		var href = "/tour/attractions/tour_total?mode=view&amp;idx="+item[0];			


		if(item[0] == "") return contents;
		if(item[3].length > 9)		title = item[3].substring(0,9)+'..';
		else	title = item[3];			

		contents_near  = "<div class=\"map_contents_near\"> ";
		contents_near  += "<div class=\"shopinfo\"> ";
		contents_near  += "<span class=\"name\"> ";
		contents_near  += "<span class=\""+item[6].toLowerCase()+"s\">"+title+"</span> ";
		contents_near  += "</span> ";
		contents_near  += "<span class=\"photo\"> ";
		if(item[9] == null || item[9] == "" ) contents_near += "<p class=\"info_img\" ></p>";
		else contents_near += "<p class=\"info_img\"><a href=\""+href+"\"><img alt=\""+item[3]+" 사진\" src=\""+item[8]+"\" /><span class=\"more\">자세히보기</span></a></p>";		
		contents_near  += "</span> ";
		contents_near  += "<span class=\"add\">"+item[4]+"</span> ";
		contents_near  += "<span class=\"tel\">"+item[5]+"</span> ";		
		contents_near  += "</div> ";
		contents_near += '	<a href="#none" class="mapinfo_close_near" onclick="closeOverlay()" >위치정보 닫기</a>';
		contents_near  += "</div> ";	
		contents_near  += "<div class=\"bottom\"></div> ";								
/*console.log( item );*/
		return contents_near;		

	}


	function bind_infowindow_near(marker_near, contents_near) {
		kakao.maps.event.addListener(marker_near, "click", function() {
			show_infowindow_near(marker_near, contents_near);
		});
	}

	function show_infowindow_near(marker_near, contents_near) {
		// 마커를 클릭했을 때 마커 위에 표시할 인포윈도우를 생성합니다
		var iwContent_near = contents_near, // 인포윈도우에 표출될 내용으로 HTML 문자열이나 document element가 가능합니다
			iwRemoveable_near = true; // removeable 속성을 ture 로 설정하면 인포윈도우를 닫을 수 있는 x버튼이 표시됩니다

		if(infowindow_near != null) infowindow_near.close();		
		// 인포윈도우를 생성합니다
		infowindow_near = new kakao.maps.InfoWindow({
			content : iwContent_near,
			removable : iwRemoveable_near
		});	

		infowindow_near.setContent(contents_near);		
		infowindow_near.open(near_map, marker_near);

		//말풍선 제어
		var map_cont_near = $(".map_contents_near");		
		map_cont_near.unwrap().siblings().remove();
		map_cont_near.parent().addClass("mapinfo_wrap_near").css({
			"height":"auto",
			"border":"0",
			"background":"none",
			"z-index": "1"
		});
	}
