	function refreshNearList(gopage, idx) {		
		if(gopage == null || gopage == 0) gopage = 1;

		$.ajax({
			url : selfUrl
			, type : "POST" /*request type(POST, GET)*/
			, dataType:"json" /*return type(xml, html, json, jsonp, script, text)*/
			, async : false /*동기화유무(true, false)*/
			, cache: false /*캐쉬사용여부(true, false)*/
			, data : {
				mode : "getTotalNearList"
				, idx : $("#map_idx").val()
				, gopage : gopage
				, page_scale : near_page_scale
				, img_size : '178x123'
			} /*보내는 데이터 request*/

			/*요청결과수신 reponse*/
			, beforeSend : /*요청보내기전선처리*/
				function (response) {
					/*alert("beforeSend");*/
				}
			, success : 
				function (json) { /*성공*/
					/*alert("success");*/
//console.log( json );

					/*if(Array.isArray(json)){  ie 저버전 에러대응*/
					if(!(json == "" || json == null || typeof(json) == "undefined")) {

						$("#around_shop").html("");
						/*$("#detail_txt").html("");*/


						var total = json.length;
						var address = json.address1+json.address2;
						if(total<1) {
							$("#detail_txt").append("<p>검색결과가 존재하지 않습니다.</p>");
						} else {
							$("#detail_txt").append('<div class="around_map kakao_map_wrapper TourMap"><div id="near_map_canvas" style="width: 100%; height: 540px;"></div><div class="map_control_box"><button class="map_btn map_zoomin"><span class="icon">확대</span></button><button class="map_btn map_zoomout"><span class="icon">축소</span></button></div></div>');

							$("#around_shop").append("<ul></ul>");
							markers_near = new Array();
							var i = 1;
							$.each(json, function(key, val) {
								var tourTel = (val.tel == null || val.tel == "") ? "" : val.tel;
								var typeTitle = "";
								var typeClass = "";
								var imgTag = "";
								if(val.title.length > 8){
									var subTitle = val.title.substr(0, 6)+"..";
								} else {
									var subTitle = val.title.substr(0, 6);
								}
/*								alert(val.address1);*/

								var marker = new Array();
								marker.push(parseFloat(val.idx));
								marker.push(parseFloat(val.wgs84_mapx));
								marker.push(parseFloat(val.wgs84_mapy));
/*								marker.push(val.title);*/
								marker.push(subTitle);								
								marker.push(val.address1);
								marker.push(tourTel);
								marker.push(val.type);
								marker.push(i+1);	
								/* 서희진 추가 */									
								marker.push(val.img_url);		
								marker.push(val.re_name);
								markers_near.push(marker);


								if(val.type == "FOOD") {
									typeTitle = "음식점";
									typeClass = "around_food";
								} else if(val.type == "LODG") {
									typeTitle = "숙박";
									typeClass = "around_stay";
								} else if(val.type == "TOUR") {
									typeTitle = "관광";
									typeClass = "around_tour";
								} else if(val.type == "TRAFFIC") {
									typeTitle = "교통";
									typeClass = "around_car";
								} else if(val.type == "SHOP") {
									typeTitle = "상점";
									typeClass = "around_shop2";
								} else {
									typeTitle = "관광지";
									typeClass = "around_etc";
								}

								var href = "?mode=view&amp;idx="+val.idx;
								if(val.module_path == null || val.module_path == "" || val.board_id == null || val.board_id == "" || val.re_name == null || val.re_name == "" ) {
									imgTag = '<a href="'+href+'" class="null"></a>';
								} else {
									if(val.re_name == null){
									imgTag = '<a href="'+href+'"><img src="/no_image.jpg" alt="'+val.img_title+'" /></a>';											
									}else{
									imgTag = '<a href="'+href+'"><img src="/ybmodule.file'+val.module_path+'/'+val.board_id+'/178x123/'+val.re_name+'" alt="'+val.img_title+'" /></a>';	
									}
									/* imgTag = '<a href="'+href+'"><img src="'+val.img_url+'" alt="'+val.img_title+'" /></a>'; */
								}

								$("#around_shop ul").append('<li><div style="width:178px; height:123px;">'+imgTag+'</div><div class="shop_info '+typeClass+'"><strong><a href="'+href+'">'+subTitle+'</a></strong><span>'+tourTel+'</span></div></li>');
								i++;
							});

							var pre_page = ((gopage-1)<1) ? 1 : gopage-1;
							var next_page = gopage+1;
							$("#around_shop").append('<a class="shop_prev" onclick="refreshNearList('+pre_page+'); return false;" href="#">이전 목록'+json.total_count + '/' +  json.page+'</a>');
							$("#around_shop").append('<a class="shop_next" onclick="refreshNearList('+next_page+'); return false;" href="#">다음 목록</a>');
							near_page = gopage;

							var nearMap = document.getElementById("near_map_canvas"); 
							var near_mapContainer = nearMap, // 지도를 표시할 div 
							near_mapOption = { 
								center: new kakao.maps.LatLng( nearCenter[1]+0.004, nearCenter[0] ), // 지도의 중심좌표
								level: 5 // 지도의 확대 레벨
							};

							near_map = new kakao.maps.Map(near_mapContainer, near_mapOption); // 지도를 생성합니다

							// 지도 확대, 축소 컨트롤에서 확대 버튼을 누르면 호출되어 지도를 확대하는 함수
							function zoomIn() {
								near_map.setLevel(near_map.getLevel() - 1, {animate: true});
							}
							// 지도 확대, 축소 컨트롤에서 축소 버튼을 누르면 호출되어 지도를 확대하는 함수
							function zoomOut() {
								near_map.setLevel(near_map.getLevel() + 1, {animate: true});
							}

							$(document).on("click", ".map_control_box button", function(){
								var $this  = $(this);

								if($this.hasClass("map_zoomin")){
									zoomIn();
								}else if($this.hasClass("map_zoomout")){
									zoomOut();
								}
							});

							initMapNear(near_map, markers_near,idx);

						}
					} else {
						/*alert(json.cate + " , " + json.reg_ip);*/
						$("#detail_txt").append("<p>검색결과가 존재하지 않습니다.</p>");
					}				
				}
			, error : /*에러*/
				function (response) {
					/*alert("error");*/
				}
			, complete : /*완료후*/
				function(response, textStatus, XMLHttpRequest){
					/*alert("complete");*/
				}
		});	
		return true;	
