				selectors = JSON.parse(localStorage.getItem("selectors"));	//메뉴 정보가 로컬스토리지에 있을경우 가져오기




		if(selectors !== null){
			//소스상 메뉴 셀렉터가 변경 될 경우 변경 된 내용을 로컬스토리지 정보에 반영
			if(selectors.length === selectors_orig.length){
				selectors_orig.forEach(function(obj, idx, arr){
					if(obj.circle !== selectors[idx]["circle"]){
						selectors[idx]["circle"] = obj.circle;
					}

					if(obj.group !== selectors[idx]["group"]){
						selectors[idx]["group"] = obj.group;
					}

					if(obj.type !== selectors[idx]["type"]){
						selectors[idx]["type"] = obj.type;
					}
				});

