	function initMainRecommendedMenu(days){
		$.ajax({
			url: "/open_content/main/member/member2HighestMenuJson.do",
			type: 'POST',
			data:{
				"days": days
			},
			timeout:3000,
			success: function(data){
				var return_value = data.return_value;
				var return_code = data.return_code;

				if(return_code === "0000"){
					var menu_arr = [];
					var menuCnt = $(".customMenu_exposure li").length;

					return_value.forEach(function(menu, idx1, arr1){
						var filtered_menu = selectors_orig.filter(function(selector, idx2, arr2){
							return menu.MENU_URI === selector.circle.href;
						});

						if(filtered_menu.length > 0){
							menu_arr.push(filtered_menu[0]);
						}
					});

					menu_arr.forEach(function(menu, idx, arr){
						if(idx < menuCnt){
							$($(".customMenu_exposure li a").get(idx)).attr("href", menu.circle.href);
							$($(".customMenu_exposure li a img").get(idx)).attr("src", "" + menu.circle.image);
							$($(".customMenu_exposure li a p.tag").get(idx)).text(menu.type);
							$($(".customMenu_exposure li a p.ttl").get(idx)).text(menu.circle.text);
						}
					});
				}
			},
			error:function(){
				console.log("회원별 자주 찾는 메뉴 정보를 불러오는데 실패했습니다.");
			}
		});
	}

