	//마이페이지 즐겨찾기 설정 목록 표출
	function favoriteList(){
		var types = [];
		selectors.forEach(function(value, index, array){
			if(types.indexOf(value.type) < 0){
				types.push(value.type);
			}
		});

		var html = "";

		types.forEach(function(value, index, array){
			var list;
			html += '<div class="favorite_manage">';
			html += '<h4>'+value+'</h4>';
			html += '<ul class="favorite_list">';

			list = selectors.filter(function(obj){
				return obj["type"] === value && obj["selectorNm"].indexOf('selector3') < 0;
			});

			list.forEach(function(value2, index2, array2){
				var checked = "";
				if(value2.selectorNm.indexOf("selector2")>-1){
					checked = "checked";
				}

				if(value2.circle.text !== '설정'){	//설정만 제외하고 표출
					html += '<li><label>'
					html += '<img src="'+value2.circle.image+'" alt="" width="30" />' + value2.circle.text
					html += '<input type="checkbox" '+checked+' title="'+value2.circle.text+' 즐겨찾기 여부 체크" onclick="editSelectorNm(this);"/>';
					html += '</label></li>'
				}
			});

			html += '</ul>';
			html += '</div>';
		});

		$("#favorite_list").html(html);
	}

	function editSelectorNm(e){
		var isChecked = $(e).is(":checked");
		var text = $(e).attr("title").replace(" 즐겨찾기 여부 체크", "");
		var currentCnt = 0;

		/*if(!isMax){*/
		if(isChecked){
			selectors.forEach(function(value, index, array){
				if(value.circle.text === text){
					array[index]["selectorNm"] = array[index]["selectorNm"] + ",selector2";
				}
			});
		}else{
			selectors.forEach(function(value, index, array){
				if(value.circle.text === text){
					array[index]["selectorNm"] = array[index]["selectorNm"].replaceAll(",selector2", "");
				}
			});
		}

		currentCnt = selectors.filter(function(obj){
			return obj.selectorNm.indexOf(",selector2") > -1;
		}).length;

		if(currentCnt > 11){	//즐겨찾기 항목까지 포함해서 11개가 맥시멈
			alert("즐겨찾기는 최대 10개까지 등록 가능 합니다.");
			selectors.forEach(function(value, index, array){
				if(value.circle.text === text){
					array[index]["selectorNm"] = array[index]["selectorNm"].replaceAll(",selector2", "");
				}
			});

			$(e).prop("checked", false);
		}
	}

