	function saveFavorites(){
		if(confirm("즐겨찾기를 저장 하시겠습니까?")){
			localStorage.setItem("selectors", JSON.stringify(selectors));
			saveFavoritesToDB(JSON.stringify(selectors));
			alert("즐겨찾기가 저장 되었습니다.");
