	//즐겨찾기 초기화 (로컬스토리지, DB에서 날리기)
	function resetFavorites(){
		if(confirm("즐겨찾기를 초기화 하시겠습니까?")){
			localStorage.removeItem("selectors");
			saveFavoritesToDB("");
			alert("즐겨찾기가 초기화 되었습니다.");
