	function initEvents(){
		$(".customMenu_toggle_btn").click(function(){
			$(this).toggleClass('close');
			$(this).text($(this).text() === '닫기'? "주요서비스 목록 열기" : "주요서비스 목록 닫기");
			$(".customMenu_toggle").toggleClass('customMenu_toggle-open');
			setPCMenu();
		});

		if(!isPc()){
			$(".header, .con3, footer, #detail_con").hammer().on("swiperight", function(e){	//모바일 우측 메뉴 호출 제스쳐 이벤트
				console.log(e);
				$(".allmenu_list").animate({"left":"0"},300);
				$("body").addClass('hidden-y');
				$(".customMenu").addClass('hidden-back');
			});

			$(".allmenu_list, .allmenu_sub").hammer().on("swipeleft", function(e){	//모바일 우측 메뉴 닫기 제스쳐 이벤트
				$(".allmenu_list").animate({"left":"-100%"},300);
				$("body").removeClass('hidden-y');
				$(".customMenu").removeClass('hidden-back');
			});
		}else{
			setPCMenu();
		}

		$(".board_tab a").click(function(){
			var idx = $(".board_tab a").index(this);

			$(".board_tab").removeClass('on');
			$(this).parent().addClass('on');
			$(".board_list").removeClass('board_list-view slide_to_right slide_to_left');
			$(".board div div.board_list").eq(idx).addClass('board_list-view');
		});

		$(".board_mb_guide").hammer().on("swipe", function(){
			$(this).hide();

			setTimeout(function(){
				$(".board").hammer().on("swipe", function(e){	//모바일 메인페이지 게시판 영역 스와이프 적용
					var currentHeaderElem = $(".board_tab div h2 a.on");
					var currentContentsElem = $(".board_list-view");

					$(".board_mb_guide").hide();	//가이드 가리기

					if(e.gesture.overallVelocity > 0){	//오른쪽 스와이프일 경우 (속도가 0일경우는 움직임이 아니므로 제외시킴)
						var prevHeaderElem = $(currentHeaderElem).parent().prev().find("a");
						var prevContentsElem = $(currentContentsElem).parent().prev().find("div");

						if(prevHeaderElem.is("a") && prevContentsElem.is("div")){
							$('.board_tab').animate({scrollLeft: prevHeaderElem.offset().left}, 500);
							$(".board_tab div h2 a").removeClass('on');
							prevHeaderElem.addClass('on');

							$(".board_list").removeClass('board_list-view');
							$(".board_list").removeClass('slide_to_right');
							$(".board_list").removeClass('slide_to_left');
							prevContentsElem.addClass('board_list-view');
							prevContentsElem.addClass('slide_to_right');
						}
					}else if(e.gesture.overallVelocity < 0){ //왼쪽 스와이프일 경우 (속도가 0일경우는 움직임이 아니므로 제외시킴)
						var nextHeaderElem = $(currentHeaderElem).parent().next().find("a");
						var nextContentsElem = $(currentContentsElem).parent().next().find("div");

						if(nextHeaderElem.is("a") && nextContentsElem.is("div")) {
							$('.board_tab').animate({scrollLeft: currentHeaderElem.offset().left}, 500);
							$(".board_tab div h2 a").removeClass('on');
							nextHeaderElem.addClass('on');

							$(".board_list").removeClass('board_list-view');
							$(".board_list").removeClass('slide_to_right');
							$(".board_list").removeClass('slide_to_left');
							nextContentsElem.addClass('board_list-view');
							nextContentsElem.addClass('slide_to_left');
						}
					}
				});
			},500);
		});
	}

