	function setPCMenu(){
		var html = "";
		var pcMenu = {};

		$.each(selectors, function(index, item){
			if(item.selectorNm.indexOf("selector1") > -1 || item.selectorNm.indexOf("selector2") > -1){
				pcMenu[item.group] = selectors.filter(function(obj) {
					return obj["selectorNm"].indexOf(item.selectorNm) > -1 && obj["circle"]["text"].indexOf("설정") < 0;
				});
			}
		});

		$.each(pcMenu, function(index, item){
			var headerText = index;
			console.log(index);
			if(headerText === "주요서비스" || headerText === "즐겨찾기"){
				html += "<h2>"+ headerText +"</h2>";
				html += "<ul>";

				$.each(item, function(index, obj){
					var text = obj.circle.text;
					var href = "";
					var target = "";
					var image_src = "";

					if(obj.circle.href !== undefined){
						href = obj.circle.href;
					}

					if(obj.circle.target !== undefined){
						target = obj.circle.target;
					}

					html += "<li><a href='"+href+"' target='"+target+"'>";

					if(obj.circle.image !== undefined){
						image_src = obj.circle.image;
						html += "<div class='ic'><img src='" + image_src + "' alt=''/></div>";
					}

					html += "<p class='ttl'>"+text+"</p>";
					html += "</a></li>";
				});

				html += "</ul>";
			}
		});
		console.log(pcMenu);
		$("#wheel").html(html);
	}

	function setMenu(selectorId, idx){
		var cnt = selectors.filter(function(obj) {
			if (selectorId === null || selectorId === undefined) {
				return obj;
			} else {
				return obj["selectorNm"].indexOf(selectorId) > -1;
			}
		}).length;

		if(selectors[idx]["selectorNm"].indexOf(selectorId) > -1){ //이미 있을경우 빼기
			if(cnt > 1){
				selectors[idx]["selectorNm"] = selectors[idx]["selectorNm"].replaceAll("," + selectorId, "");
				$(".setBtn").eq(idx).text("+");
			}else{
				alert("표시 되는 메뉴는 1개 이상이어야 합니다. ");
			}
		}else{
			selectors[idx]["selectorNm"] += "," + selectorId;	 //없을 경우 더하기
			$(".setBtn").eq(idx).text("-");
		}

		localStorage.setItem("selectors", JSON.stringify(selectors));

		optionsObj["selectorId"] = selectorId;

		initCircleWheel("wheel", getCircleArray(selectorId), optionsObj);
	}

	function drawMenuList(selectorId){
		var html="";

		getCircleArray().forEach(function(obj, idx, arr){
			var btnTxt = obj.getText();
			var setBtnText="";

			if(selectors[idx]["selectorNm"].indexOf(selectorId) > -1){
				setBtnText = "-";
			}else{
				setBtnText = "+";
			}

			html += "<li><span>"+btnTxt+": </span><button class='setBtn' data-idx='"+idx+"'>"+setBtnText+"</button></li>";
		});

		$("#menuList").html("<ul>"+html+"</ul>");
	}

	function getCircleArray(selectorId){	//데이터 필터 후 가공

		if(isPc()){
