		// 현재 페이지가 index.php 또는 main.php 인 경우에는 서브메뉴 기본 닫기
		if (window.location.href.indexOf('index.php') > -1 || window.location.href.indexOf('main.php') > -1) {
			$("ul.navi_mb ul.sub2").hide();
		} else {
			$("ul.navi_mb ul.sub2").hide();
			$("ul.navi_mb li.now ul.sub2").show();
			$("ul.navi_mb li.now > a i.xi-plus-thin")
				.removeClass("xi-plus-thin")
				.addClass("xi-minus-thin");
		}

		// 1차 메뉴 클릭 시 동작
		$("ul.navi_mb > li > a").click(function(e){
			const $li = $(this).parent("li");
			const $sub = $("ul.sub2", $li);
			const $icon = $("i", this);

			// 하위 메뉴가 있는 경우에만 토글
			if ($sub.length > 0) {
				e.preventDefault(); // 링크 이동 방지
				$sub.slideToggle("fast", function(){
					if ($sub.is(":visible")) {
						$icon.removeClass("xi-plus-thin").addClass("xi-minus-thin");
					} else {
						$icon.removeClass("xi-minus-thin").addClass("xi-plus-thin");
					}
				});
			}
			// 하위 메뉴가 없으면 링크 정상 이동 (preventDefault 안 걸림)
		});

		// 2차 메뉴 이하의 링크는 클릭 시 상위 이벤트 방지 (정상 링크 작동)
		$("ul.navi_mb ul.sub2 a, ul.navi_mb ul.sub3 a, ul.navi_mb ul.sub4 a").click(function(e){
			e.stopPropagation(); // 상위 li 클릭 이벤트로 버블링 방지
			// 링크 이동은 막지 않음
		});

	});', '본 웹사이트에 게시된 이메일 주소가 전자우편 수집 프로그램이나 그 밖의 기술적 장치를 이용하여무단으로 수집되는 것을 거부하며, 위반시 정보통신망법에 의해 형사처벌됩니다..']

