["$(function() {
		var $list = $('.latest_aca_list ul');
		var itemHeight = 60;
		var speed = 1000;
		var delay = 2000;
		var rollingTimer = null;
		var currentTop = 0;
		var clonedAppended = false;

		// li 개수가 1개 이하이면 롤링 불필요
		if ($list.children().length <= 1) return;

		// 원본 li 저장 (초기 한 번만 복제)
		function ensureCloned() {
			if (clonedAppended) return;
			var $items = $list.children();
			var $cloned = $items.clone();
			$list.append($cloned);
			clonedAppended = true;
		}

		// 총 높이(원본+클론)
		function calcTotalHeight() {
			return itemHeight * $list.children().length;
		}

		function startRolling() {
			if (rollingTimer) return; // 이미 동작중이면 무시
			ensureCloned();
			var totalHeight = calcTotalHeight();

			function roll() {
				currentTop -= itemHeight;
				$list.animate({ top: currentTop }, speed, 'linear', function() {
					if (Math.abs(currentTop) >= totalHeight / 2) {
						currentTop = 0;
						$list.css({ top: 0 });
					}
					rollingTimer = setTimeout(roll, delay);
				});
			}

			// 첫 실행 지연 후 시작
			rollingTimer = setTimeout(roll, delay);
		}

		function stopRolling() {
			if (!rollingTimer && $list.is(':animated') === false) return;
			clearTimeout(rollingTimer);
			rollingTimer = null;
			$list.stop(true, true); // 애니메이션 정지
			// 멈출 때 위치 초기화 (원하면 유지하도록 변경 가능)
			currentTop = 0;
			$list.css({ top: 0 });
		}

		function checkWidthAndToggle() {
			if ($(window).width() >= 1161) {
				// 1161 이상일 때 롤링 켜기
				startRolling();
			} else {
				// 1160 이하일 때 멈추기
				stopRolling();
			}
		}

		// 초기 실행
		checkWidthAndToggle();

		// resize에 debounce 적용해서 즉시 반영(너무 잦은 호출 방지)
		var resizeTimer = null;
		$(window).on('resize', function() {
			clearTimeout(resizeTimer);
			resizeTimer = setTimeout(checkWidthAndToggle, 120);
		});
	});", '본 웹사이트에 게시된 이메일 주소가 전자우편 수집 프로그램이나 그 밖의 기술적 장치를 이용하여무단으로 수집되는 것을 거부하며, 위반시 정보통신망법에 의해 형사처벌됩니다..']

