["const fireflyCount = 40;
    const container = document.querySelector('.main_program');
    const containerWidth = container.clientWidth;
    const containerHeight = container.clientHeight;

    for (let i = 0; i < fireflyCount; i++) {
      const firefly = document.createElement('div');
      firefly.classList.add('firefly');
      container.appendChild(firefly);

      // 초기 위치
      firefly.style.left = Math.random() * containerWidth + 'px';
      firefly.style.top = Math.random() * containerHeight + 'px';

      // 개별 애니메이션 설정
      firefly.style.animationDuration = (1.5 + Math.random() * 2) + 's';
      firefly.style.animationDelay = Math.random() * 2 + 's';

      // 이동 애니메이션
      firefly.animate([
        { transform: 'translate(0, 0)' },
        {
          transform: `translate(${Math.random() * 100 - 50}px, ${Math.random() * 100 - 50}px)`
        },
        { transform: 'translate(0, 0)' }
      ], {
        duration: 8000 + Math.random() * 5000,
        iterations: Infinity,
        direction: 'alternate',
        easing: 'ease-in-out'
      });
    }"]

